'use strict';const M=Model,U=OmniUI,$=x=>document.getElementById(x);window.OMNI_PREVIEW=!window.omnibloomHost;let s=null,busy=false,alive=true,epoch=0,revisionFloor=-1,queued=false,ownsInert=false,inertWatch=null,mock={version:1,revision:0,activeMode:'normal',privateTabs:0,isolated:true,noHistory:true,canEndSession:true};function draw(){const ready=alive&&!!s&&!busy;$('refresh').disabled=!alive||busy;$('confirm-close').disabled=!ready||!s?.canEndSession||!s?.privateTabs;$('new').disabled=!ready||s.privateTabs>=64;$('close-private').disabled=!ready||!s.canEndSession||!s.privateTabs;$('badge').textContent=window.OMNI_PREVIEW?'INTERACTIVE PREVIEW':'SESSION STATUS';$('mode').textContent=s?M.label(s):'Private status unavailable';$('detail').textContent=s?s.privateTabs+' private tabs open. '+(s.canEndSession?'You can end the private session here.':'Private data is cleared when Omni closes.'):'No privacy guarantees can be confirmed.';document.body.dataset.mode=s?.activeMode||'unknown'}
function foreignModal(){return Array.from(document.querySelectorAll('dialog[open],[role=dialog],[role=alertdialog]')).find(e=>e!==$('confirm')&&!e.hidden&&!e.closest('[hidden]')&&e.getClientRects().length&&getComputedStyle(e).visibility!=='hidden')}
function releaseInert(){if(!ownsInert)return;ownsInert=false;$('content').removeAttribute('inert')}
function settleInert(){if(!ownsInert||!$('confirm').hidden)return;if(!foreignModal()){releaseInert();return}if(inertWatch)return;inertWatch=new MutationObserver(()=>{if(!$('confirm').hidden||foreignModal())return;inertWatch.disconnect();inertWatch=null;releaseInert();const e=document.activeElement;if(alive&&(e===document.body||!e?.isConnected||e.closest('[hidden]')))U.focus($('refresh'))});inertWatch.observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['hidden','open']})}
function pendingFocus(){const e=document.activeElement;if(e&&['new','close-private','confirm-close'].includes(e.id)){const target=e.closest('#confirm')?$('dialog-error'):$('status');target.tabIndex=-1;target.focus();return {target,id:e.id}}return null}
function recover(f){if(f&&document.activeElement===f.target&&!foreignModal()){const e=$(f.id);if(e&&!e.disabled&&!e.closest('[hidden]'))U.focus(e);else if(!$('refresh').disabled)U.focus($('refresh'))}}
async function load(){if(!alive)return;if(busy){queued=true;return}const token=++epoch;try{const next=M.validate(await U.request('privacy.status',{},()=>mock));if(!alive||token!==epoch||busy)return;if(next.revision<revisionFloor){if(!s)U.notify('Unable to verify session state.');return}revisionFloor=next.revision;s=next;U.notify(window.OMNI_PREVIEW?'Simulated session · no browser session has changed.':'Session state confirmed.')}catch(_){if(!alive||token!==epoch||busy)return;s=null;U.notify('Unable to verify session state.')}finally{if(alive&&token===epoch&&!busy){const f=pendingFocus();draw();recover(f)}}}
async function act(type){if(!alive||busy||!s)return;const base=s,params=M.action(base,type),token=++epoch,f=pendingFocus();busy=true;draw();try{const next=M.validate(await U.request(type==='new'?'privacy.openTab':'privacy.endSession',params,()=>{mock={...mock,revision:mock.revision+1,activeMode:type==='new'?'private':'normal',privateTabs:type==='new'?mock.privateTabs+1:0};return mock}));if(!alive||token!==epoch)return;if(next.revision<=base.revision||next.revision<revisionFloor||type==='new'&&next.activeMode!=='private'||type==='end'&&next.privateTabs!==0)throw Error('Unconfirmed transition');revisionFloor=next.revision;s=next;if(type==='end'){const foreground=foreignModal(),owned=$('confirm').contains(document.activeElement);if(!foreground||!$('confirm').contains(foreground))$('confirm').hidden=true;settleInert();if(!foreground){if(owned){const t=$('status');t.tabIndex=-1;t.focus()}}}U.notify(window.OMNI_PREVIEW?'Preview updated.':'Private session updated.')}catch(_){if(!alive||token!==epoch)return;$('dialog-error').textContent='The operation was not confirmed. Refresh status before retrying.';U.notify('Session operation was not confirmed.');s=null}finally{busy=false;if(alive){draw();settleInert();if(token===epoch)recover(f);if(queued){queued=false;load()}}}}
$('new').onclick=()=>act('new');$('close-private').onclick=()=>{if(!alive||busy||!s)return;$('dialog-error').textContent='';ownsInert=!$('content').hasAttribute('inert');U.modal('confirm')};$('confirm-close').onclick=()=>act('end');$('refresh').onclick=load;window.addEventListener('omni-privacy-changed',load);
window.addEventListener('pagehide',()=>{alive=false;++epoch;queued=true;s=null;$('confirm').hidden=true;inertWatch?.disconnect();inertWatch=null;releaseInert();draw()});
window.addEventListener('pageshow',e=>{if(!e.persisted)return;alive=true;draw();if(busy){queued=true;return}queued=false;load()});
